'use strict';
const $=id=>document.getElementById(id),D=Cost.defaults;
const fields={usageFields:[['days','每月使用天数',0,31,1],['tasks','每天完成任务数',0,10000,1],['creditTask','WorkBuddy 积分 / 任务',0,1e6,'any'],['input','输入 Token / 任务',0,1e9,1],['output','输出 Token / 任务',0,1e9,1],['cache','输入缓存命中率（%）',0,100,'any'],['multiplier','API 调用 / 重试倍率',1,100,'any']],wbFields:[['bill','账期价格（原币）',0,1e7,'any'],['months','每账期月数',1,120,1],['credits','基础积分 / 月',0,1e9,'any'],['gift','限时赠送积分 / 月',0,1e9,'any'],['packCredits','每包积分',1,1e9,'any'],['packPrice','每包价格（原币）',0,1e7,'any']],apiFields:[['inputPrice','未命中输入 / 百万 Token',0,1e6,'any'],['cachePrice','缓存命中 / 百万 Token',0,1e6,'any'],['outputPrice','输出 / 百万 Token',0,1e6,'any'],['fx','美元兑人民币（假设）',.01,100,'any']],extraFields:[['fee','API 附加费率（%）',0,1000,'any'],['tool','工具费（元 / 任务）',0,1e6,'any'],['fixed','API 固定费（元 / 月）',0,1e7,'any'],['setup','API 一次搭建投入（元）',0,1e7,'any'],['amort','搭建费摊销月数',1,120,1],['hourly','时间价值（元 / 小时）',0,1e6,'any'],['wbMinutes','WorkBuddy 人工分钟 / 任务',0,1e5,'any'],['apiMinutes','API 人工分钟 / 任务',0,1e5,'any'],['limit','临界点扫描上限（任务 / 月）',1,100000,1]]};
for(const [group,items] of Object.entries(fields))for(const [id,label,min,max,step]of items){const l=document.createElement('label');l.textContent=label;const input=document.createElement('input');Object.assign(input,{id,type:'number',min:String(min),max:String(max),step:String(step),required:true});l.append(input);$(group).append(l)}
let s={...D};
function fill(){for(const key of Object.keys(D)){if(typeof D[key]==='boolean')$(key).checked=s[key];else $(key).value=s[key]}}
function read(){const next={...s};for(const key of Object.keys(D)){const el=$(key);if(typeof D[key]==='number'){if(!el.checkValidity())return false;next[key]=Number(el.value)}else next[key]=typeof D[key]==='boolean'?el.checked:el.value}s=next;return true}
function loadHash(){s={...D};if(!location.hash)return;try{const q=new URLSearchParams(location.hash.slice(1));if(q.get('v')!=='1')throw Error();for(const key of Object.keys(D)){if(!q.has(key))continue;const val=q.get(key);if(typeof D[key]==='number'){const field=Object.values(fields).flat().find(x=>x[0]===key),n=Number(val);if(val.trim()===''||!Number.isFinite(n)||n<field[2]||n>field[3]||(field[4]===1&&!Number.isInteger(n)))throw Error();s[key]=n}else if(typeof D[key]==='boolean'){if(!['0','1'].includes(val))throw Error();s[key]=val==='1'}else{if(!Array.from($(key).options).some(o=>o.value===val))throw Error();s[key]=val}}$('status').textContent='已载入分享参数。价格是链接中的快照，可继续修改。'}catch{s={...D};$('status').textContent='分享参数无效或版本不支持，已恢复默认值。'}}
const money=n=>'¥'+n.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}),num=n=>n.toLocaleString('zh-CN',{maximumFractionDigits:2});
const plans={standard:{monthly:99,auto:70,annual:840,annualAuto:672,credits:2000,gift:2000},advanced:{monthly:199,auto:140,annual:1680,annualAuto:1344,credits:4000,gift:5000},flagship:{monthly:999,auto:700,annual:8400,annualAuto:6720,credits:20000,gift:30000},global:{monthly:10,auto:10,annual:96,annualAuto:96,credits:1000,gift:1000}};
function planPreset(){const p=plans[s.plan];if(!p)return;Object.assign(s,{bill:p[s.cycle],months:s.cycle.startsWith('annual')?12:1,credits:p.credits,gift:p.gift,packCredits:s.plan==='global'?500:1000,packPrice:s.plan==='global'?15:50,wbCurrency:s.plan==='global'?'USD':'CNY'});fill()}
const models={proPeak:[1.32,.044,3.96],proOff:[.66,.022,1.98],flashPeak:[.3,.006,1.2],flashOff:[.15,.003,.6],router:[.03,.03,1.28]};
function draw(){const max=Math.max(1,s.days*s.tasks*2),W=570,H=206,x=n=>52+n/max*W;const cs=Array.from({length:501},(_,i)=>Cost.calc(s,max*i/500)),top=Math.max(1,...cs.flatMap(c=>[c.wb,c.api]))*1.1,y=v=>230-v/top*H;let svg='';for(let i=0;i<5;i++){const v=top*i/4;svg+=`<line x1="52" y1="${y(v)}" x2="622" y2="${y(v)}" stroke="#e3e9df"/><text x="44" y="${y(v)+4}" text-anchor="end" fill="#66766f" font-size="10">${num(v)}</text>`}for(let i=0;i<5;i++)svg+=`<text x="${x(max*i/4)}" y="253" text-anchor="middle" fill="#66766f" font-size="10">${num(max*i/4)}</text>`;for(const[key,color]of[['wb','#176448'],['api','#ac552b']]){svg+=`<polyline fill="none" stroke="${color}" stroke-width="2.5" points="${cs.map((c,i)=>`${x(max*i/500)},${y(c[key])}`).join(' ')}"/>`}const n=s.days*s.tasks;svg+=`<line x1="${x(n)}" y1="12" x2="${x(n)}" y2="230" stroke="#819078" stroke-dasharray="4 4"/><text x="${x(n)+6}" y="18" fill="#66766f" font-size="10">当前 ${num(n)} 次</text>`;$('chart').innerHTML=svg;$('chartNote').textContent=`横轴：月任务数（0–${num(max)}）。曲线采用 501 点抽样，细小阶梯可能省略；临界点使用下方逐整数精算。`}
function syncScene(){const scenes={light:{days:20,tasks:5,input:3000,output:1000,creditTask:5,cache:0,multiplier:1},office:{days:22,tasks:10,input:30000,output:5000,creditTask:20,cache:20,multiplier:1},heavy:{days:22,tasks:30,input:300000,output:30000,creditTask:100,cache:50,multiplier:1}};document.querySelectorAll('[data-scene]').forEach(b=>{const x=scenes[b.dataset.scene];b.classList.toggle('selected',x&&['days','tasks','input','output','creditTask','cache','multiplier'].every(k=>s[k]===x[k]))})}
function render(){document.querySelector('.workspace').classList.remove('invalid');syncScene();const c=Cost.calc(s),diff=c.wb-c.api;$('taskTotal').textContent=num(c.n)+' 个任务';$('winner').textContent=Math.abs(diff)<1e-7?'两种方案成本基本相同':diff>0?'当前用量，API 更省。':'当前用量，WorkBuddy 更省。';$('saving').textContent=`按当前假设，每月相差 ${money(Math.abs(diff))}。${s.hourly?'已计入人工时间价值。':'尚未计入人工时间价值。'}`;$('wbTotal').textContent=money(c.wb);$('apiTotal').textContent=money(c.api);
const rows=[['订阅 / 固定及搭建摊销',c.subscription,c.apiFixed],['积分加量 / API 用量',c.topup,c.apiUsage],['人工时间折算',c.wbTime,c.apiTime],['月成本合计',c.wb,c.api],['每任务成本',c.n?c.wb/c.n:null,c.n?c.api/c.n:null]];$('billRows').innerHTML=rows.map(r=>`<tr><td>${r[0]}</td><td>${r[1]===null?'—':money(r[1])}</td><td>${r[2]===null?'—':money(r[2])}</td></tr>`).join('');$('quotaNote').textContent=`需要 ${num(c.used)} 积分，月额度 ${num(c.quota)}；补充 ${num(c.packs)} 包，余 ${num(c.remaining)} 积分。未用余额不折现、不结转。`;$('upfront').textContent=`订阅当期预付 ${money(c.upfront)}（覆盖 ${s.months} 个月）；上方按月摊销。API 搭建投入 ${money(s.setup)} 分 ${s.amort} 月摊销。这里估算费用，不是充值现金流。`;
const rr=Cost.ranges(s);$('breakSummary').textContent=`扫描 0–${num(s.limit)} 个任务/月，发现 ${rr.length-1} 次优势状态切换。${c.n>s.limit?'当前用量超出扫描范围，请提高上限。':''}`;$('breaks').innerHTML=rr.slice(0,8).map(r=>`<div class="range"><span>${num(r.start)}${r.end===r.start?'':'–'+num(r.end)} 次 / 月</span><b>${r.winner==='wb'?'WorkBuddy 更省':r.winner==='api'?'API 更省':'成本相同'}</b></div>`).join('')+(rr.length>8?`<p class="help">共 ${rr.length} 个区间，仅展示前 8 个。整包加购可造成反复切换。</p>`:'');
$('wbNote').textContent=s.plan==='global'?'国际 Pro 使用美元计价；自动续费选项与普通月 / 年付采用同价，未假定额外折扣。':'国内套餐：官方限时赠送未明确长期截止日期，默认不计。符合条件的老用户保价可能为 ¥58/月（至 2026-12-31），请手动改价。';$('apiNote').textContent=s.model==='router'?'动态参考：2026-10-10 Models API 返回 $0.03 / $0.03 / $1.28（未命中 / 命中 / 输出，每百万 Token）。网页标价不同，须按实际路由账单校准；附加费默认 0，充值手续费待补。':s.model==='custom'?'自定义价格：请根据服务商账单填写输入、缓存、输出价格及附加费。当前数值沿用上个选择，尚未核实。':'来源：DeepSeek 官方定价（2026-10-10 核对）。价格单位为每百万 Token；切换预设会重置三项单价为美元。修改后的输入优先于预设名称。';draw()}
$('form').addEventListener('submit',e=>e.preventDefault());$('form').addEventListener('input',e=>{if(!read()){document.querySelector('.workspace').classList.add('invalid');return}if(['plan','cycle'].includes(e.target.id))planPreset();if(e.target.id==='model'&&models[s.model]){[s.inputPrice,s.cachePrice,s.outputPrice]=models[s.model];s.apiCurrency='USD';fill()}render()});
for(const b of document.querySelectorAll('[data-scene]'))b.addEventListener('click',()=>{const scene={light:{days:20,tasks:5,input:3000,output:1000,creditTask:5,cache:0,multiplier:1},office:{days:22,tasks:10,input:30000,output:5000,creditTask:20,cache:20,multiplier:1},heavy:{days:22,tasks:30,input:300000,output:30000,creditTask:100,cache:50,multiplier:1}}[b.dataset.scene];Object.assign(s,scene);fill();render();document.querySelectorAll('[data-scene]').forEach(el=>el.classList.toggle('selected',el===b))});
$('reset').addEventListener('click',()=>{s={...D};history.replaceState(null,'',location.pathname+location.search);$('status').textContent='已恢复默认示例。';$('shareBox').hidden=true;fill();render()});
$('share').addEventListener('click',async()=>{if(!read()){$('status').textContent='请先修正无效输入，再分享。';return}const q=new URLSearchParams({v:'1'});for(const [k,v]of Object.entries(s))q.set(k,typeof v==='boolean'?(v?'1':'0'):String(v));const url=new URL(location.href);url.hash=q.toString();history.replaceState(null,'',url);$('shareUrl').value=url.href;$('shareBox').hidden=false;try{await navigator.clipboard.writeText(url.href);$('status').textContent='链接已复制，包含全部价格与用量参数。'}catch{$('shareUrl').select();$('status').textContent='请复制下方完整链接。'}});
window.addEventListener('hashchange',()=>{loadHash();fill();render()});loadHash();fill();render();
